SELECT
  snapshot_date,
  observation_cutoff_at,
  report_date,
  DATE_TRUNC(report_date, MONTH) AS report_month,
  CASE
    WHEN report_date BETWEEN DATE '2026-07-01' AND DATE '2026-07-07' THEN DATE '2026-07-01'
    WHEN report_date BETWEEN DATE '2026-07-08' AND DATE '2026-07-14' THEN DATE '2026-07-08'
    WHEN report_date BETWEEN DATE '2026-07-15' AND DATE '2026-07-21' THEN DATE '2026-07-15'
    WHEN report_date BETWEEN DATE '2026-07-22' AND DATE '2026-07-28' THEN DATE '2026-07-22'
  END AS period_start_date,
  CASE
    WHEN report_date BETWEEN DATE '2026-07-01' AND DATE '2026-07-07' THEN DATE '2026-07-07'
    WHEN report_date BETWEEN DATE '2026-07-08' AND DATE '2026-07-14' THEN DATE '2026-07-14'
    WHEN report_date BETWEEN DATE '2026-07-15' AND DATE '2026-07-21' THEN DATE '2026-07-21'
    WHEN report_date BETWEEN DATE '2026-07-22' AND DATE '2026-07-28' THEN DATE '2026-07-28'
  END AS period_end_date,
  CASE
    WHEN report_date BETWEEN DATE '2026-07-01' AND DATE '2026-07-07' THEN 'Jul 1-7'
    WHEN report_date BETWEEN DATE '2026-07-08' AND DATE '2026-07-14' THEN 'Jul 8-14'
    WHEN report_date BETWEEN DATE '2026-07-15' AND DATE '2026-07-21' THEN 'Jul 15-21'
    WHEN report_date BETWEEN DATE '2026-07-22' AND DATE '2026-07-28' THEN 'Jul 22-28'
  END AS period_label,
  agent_name,
  report_section,
  agent_name IN ('Aira L. Garcia','Rem Reyes','Rolyn Ang','Sarah') AS is_selected_four_cs,
  CASE WHEN agent_name = 'Taira (Chatbot/JCo)' THEN 'Taira' WHEN agent_name IN ('Aira L. Garcia','Rem Reyes','Rolyn Ang','Sarah') THEN 'Four-CS' ELSE 'Other' END AS comparison_group,
  actual_inquiries,
  validated_moderate_inquiries,
  booking_count,
  distinct_converted_inquiries,
  SAFE_DIVIDE(validated_moderate_inquiries, actual_inquiries) AS moderate_rate,
  SAFE_DIVIDE(booking_count, actual_inquiries) AS conversion_rate,
  SAFE_DIVIDE(distinct_converted_inquiries, actual_inquiries) AS unique_inquiry_conversion_rate,
  SAFE_DIVIDE(booking_count, validated_moderate_inquiries) AS booking_per_moderate_rate,
  'Frozen from Inquiry_Cohorts in gulong_july_booking_conversion_audit_2026-07-29.xlsx to match the 2026-07-29 PDF logic with date-filterable daily grain.' AS source_note
FROM rows;

CREATE OR REPLACE VIEW `gulong-chatbot-459723.gulong_reporting.v_looker_pdf_logic_agent_daily_2026_07_29`
OPTIONS (
  description = "Date-filterable daily PDF-logic snapshot view built from workbook Inquiry_Cohorts. Rolls up to the same Jul 1-7 / 8-14 / 15-21 / 22-28 / 1-28 numbers as the frozen PDF report layer, while allowing Looker date and agent filters."
) AS
SELECT * FROM `gulong-chatbot-459723.gulong_reporting.t_pdf_logic_agent_daily_2026_07_29`;